 void screen(String label){epoch++;if(pending!=null)pending.cancel(true);body.removeAllViews();title.setText(label);status.setText("");}
 void work(String label,Work task,Runnable retry){int token=++epoch;if(pending!=null)pending.cancel(true);status.setText(label);pending=io.submit(()->{try{Runnable done=task.run();runOnUiThread(()->{if(!dead&&token==epoch){status.setText("");done.run();}});}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;status.setText(EmbyApi.explain(e));row("重试",retry);});}});}
 void push(Runnable destination,Runnable previous){back.push(previous);destination.run();}
 void servers(){screen("Emby 服务器");JSONArray all=EmbyStore.list(this);if(all.length()==0)body.addView(text("还没有服务器。填写地址和用户名，密码没有可留空。支持 http 或 https，端口可省略。",14));
  for(int i=0;i<all.length();i++){JSONObject s=all.optJSONObject(i);if(s==null)continue;String id=s.optString("id");row(EmbyStore.label(s),()->push(()->libraries(EmbyStore.get(this,id)),this::servers));LinearLayout actions=new LinearLayout(this);actions.addView(button("编辑",()->editor(EmbyStore.get(this,id))),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("删除",()->confirmDelete(id)),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);}body.addView(button("添加服务器",()->editor(null)));}
 void confirmDelete(String id){new CinemaDialog(this).setTitle("删除这个 Emby 服务器？").setMessage("只从本机移除登录信息，不会改动服务器上的媒体。").setNegativeButton("取消",null).setPositiveButton("删除",(d,n)->{EmbyStore.delete(this,id);servers();}).show();}
 void editor(JSONObject existing){screen(existing==null?"添加服务器":"编辑服务器");EditText url=field(existing==null?"http://192.168.1.10:8096":existing.optString("url"),EmbyApi.serverHint());EditText user=field(existing==null?"":existing.optString("username"),"用户名");EditText pass=field("",EmbyApi.passwordHint(existing!=null));pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);EditText backup=field(backupText(existing),"备用地址，每行一个。主线路连不上时自动尝试");backup.setSingleLine(false);backup.setMinLines(2);body.addView(url);body.addView(user);body.addView(pass);body.addView(backup);
  body.addView(text("登录会请求 /Users/AuthenticateByName。令牌只保存在本机。",12));((TextView)body.getChildAt(body.getChildCount()-1)).setTextColor(muted());
  body.addView(button("登录并保存",()->{String address=url.getText().toString().trim(),name=user.getText().toString().trim(),password=pass.getText().toString();if(name.isEmpty()){user.setError("请填写用户名");return;}JSONArray backups;try{backups=EmbyCue.parseBackups(backup.getText().toString());for(int i=0;i<backups.length();i++)EmbyApi.server(backups.optString(i));}catch(Exception e){backup.setError(e.getMessage()==null?"备用地址无效":e.getMessage());return;}String secret=EmbyApi.loginPassword(existing!=null,password,existing==null?"":existing.optString("password"));JSONObject draft=existing==null?new JSONObject():existing;try{draft.put("url",address).put("backups",backups);}catch(Exception ignored){}
   work("正在登录…",()->{EmbyClient.authenticate(this,draft,name,secret);EmbyStore.save(this,draft);return ()->{Toast.makeText(this,"已保存 "+EmbyStore.label(draft),Toast.LENGTH_SHORT).show();servers();};},()->editor(existing));}));}
 static String backupText(JSONObject server){JSONArray list=server==null?null:server.optJSONArray("backups");if(list==null||list.length()==0)return "";StringBuilder s=new StringBuilder();for(int i=0;i<list.length();i++){if(i>0)s.append('\n');s.append(list.optString(i));}return s.toString();}
 EditText field(String value,String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setHint(hint);e.setTextColor(ink());e.setHintTextColor(muted());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(6);e.setLayoutParams(p);return e;}
 void libraries(JSONObject server){if(server==null){servers();return;}screen(server.optString("name","Emby"));work("正在读取媒体库…",()->{JSONArray items=EmbyClient.views(this,server).optJSONArray("Items");return ()->{status.setText(EmbyStore.label(server));if(items==null||items.length()==0){body.addView(text("这个账号没有可浏览的媒体库",14));return;}for(int i=0;i<items.length();i++){JSONObject v=items.optJSONObject(i);if(v==null||!EmbyApi.library(v))continue;String id=v.optString("Id"),name=v.optString("Name","媒体库");boolean hidden=EmbyCue.hidden(server,id);row((hidden?"已隐藏 · ":"")+name,()->push(()->library(server.optString("id"),id),()->libraries(EmbyStore.get(this,server.optString("id")))));String sid=server.optString("id");body.addView(button(hidden?"显示这个媒体库":"在首页隐藏",()->{try{JSONObject current=EmbyStore.get(this,sid);if(current==null)return;current.put("hidden",EmbyCue.toggleHidden(current.optJSONArray("hidden"),id));EmbyStore.save(this,current);libraries(EmbyStore.get(this,sid));}catch(Exception ignored){}}));}};},()->libraries(server));}
 void library(String serverId,String libraryId){library(serverId,libraryId,"",false);}
 void library(String serverId,String libraryId,String genre,boolean favorite){JSONObject server=EmbyStore.get(this,serverId);if(server==null){servers();return;}screen("媒体库");work("正在读取条目…",()->{JSONObject folder=EmbyClient.item(this,server,libraryId);String types="movies".equals(folder.optString("CollectionType"))?"Movie":"tvshows".equals(folder.optString("CollectionType"))?"Series":"Movie,Series";JSONObject page=EmbyClient.items(this,server,libraryId,types,0,genre,favorite);JSONArray items=page.optJSONArray("Items");int total=page.optInt("TotalRecordCount",items==null?0:items.length());JSONArray genres=new JSONArray();try{JSONArray found=EmbyClient.genres(this,server,libraryId).optJSONArray("Items");if(found!=null)genres=found;}catch(Exception ignored){}JSONArray chips=genres;return ()->{title.setText(folder.optString("Name","媒体库"));filters(serverId,libraryId,chips,genre,favorite);if(items==null||items.length()==0)body.addView(text(favorite?"收藏里暂时没有条目":"此媒体库暂时没有条目",14));else gallery(server,items,()->library(serverId,libraryId,genre,favorite));more(server,libraryId,types,items==null?0:items.length(),total,serverId,genre,favorite);};},()->library(serverId,libraryId,genre,favorite));}
 void filters(String serverId,String libraryId,JSONArray genres,String genre,boolean favorite){HorizontalScrollView scroller=new HorizontalScrollView(this);scroller.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);scroller.addView(row);chip(row,"全部",genre.isEmpty()&&!favorite,()->library(serverId,libraryId,"",false));chip(row,"收藏",favorite,()->library(serverId,libraryId,"",true));for(int i=0;genres!=null&&i<genres.length()&&i<24;i++){JSONObject g=genres.optJSONObject(i);String name=g==null?"":g.optString("Name");if(name.isEmpty())continue;chip(row,name,name.equals(genre),()->library(serverId,libraryId,name,false));}body.addView(scroller);}
 void chip(LinearLayout row,String label,boolean on,Runnable action){Button b=button(label,action);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(on?(light?0xffcee4ef:0xff315c7a):card()));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(36));lp.rightMargin=dp(8);row.addView(b,lp);}
 /** 媒体库分页：每页 100 条，点「加载更多」接着往下排。筛选条件保持不变。 */
 void more(JSONObject server,String libraryId,String types,int loaded,int total,String serverId,String genre,boolean favorite){if(loaded<=0||loaded>=total)return;Button b=button("加载更多（已显示 "+loaded+" / "+total+"）",null);b.setOnClickListener(v->{b.setEnabled(false);b.setText("正在加载…");int token=epoch;io.submit(()->{try{JSONArray next=EmbyClient.items(this,server,libraryId,types,loaded,genre,favorite).optJSONArray("Items");runOnUiThread(()->{if(dead||token!=epoch)return;body.removeView(b);gallery(server,next,()->library(serverId,libraryId,genre,favorite));more(server,libraryId,types,loaded+(next==null?0:next.length()),next==null||next.length()==0?loaded:total,serverId,genre,favorite);});}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;b.setEnabled(true);b.setText("加载失败，点此重试 · "+EmbyApi.explain(e));});}});});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);body.addView(b,p);}
 void detail(String serverId,String itemId){JSONObject server=EmbyStore.get(this,serverId);if(server==null){servers();return;}screen("影片");work("正在读取详情…",()->{JSONObject item=EmbyClient.item(this,server,itemId);String type=item.optString("Type");JSONArray seasons="Series".equals(type)?EmbyClient.seasons(this,server,itemId).optJSONArray("Items"):null;return ()->renderDetail(server,item,seasons);},()->detail(serverId,itemId));}
 int accentFill(){return light?0xff2f6f8f:0xffa2d0ed;}int accentInk(){return light?0xffffffff:0xff0c2a33;}
 /**
  * 0.1.97 详情页与 Stremio 详情同一版式：通栏背景大图 + 渐变到底色、大标题、信息行、一个主按钮、可展开简介；
  * 剧集的季用横向胶囊切换，集列表在同一页，不再多点一层。
  */
 void renderDetail(JSONObject server,JSONObject item,JSONArray seasons){try{JSONObject meta=EmbyApi.meta(server,item);title.setText("");detailExtras(server,item,meta);
  int sw=getResources().getDisplayMetrics().widthPixels,heroH=DetailLandscape.heroHeight(this,Math.min(dp(360),(int)(sw*.62f)));
  FrameLayout hero=new FrameLayout(this);hero.setTag("mp-detail-hero");ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(cover,new FrameLayout.LayoutParams(-1,-1));TvPosterImages.load(this,cover,meta.optString("background",meta.optString("poster")),sw);
  View fade=new View(this);fade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x00000000,0x00000000,(surface()&0xffffff)|0xcc000000,surface()}));hero.addView(fade,new FrameLayout.LayoutParams(-1,-1));
  body.addView(hero,DetailLandscape.heroParams(body,heroH));
  TextView name=text(meta.optString("name"),24);name.setTypeface(null,1);name.setPadding(0,dp(4),0,dp(2));LinearLayout.LayoutParams nl=new LinearLayout.LayoutParams(-1,-2);nl.topMargin=-dp(36);body.addView(name,nl);
  String facts=HomeRules.heroFacts(meta);String runtime=meta.optString("runtime");String line=facts+(runtime.isEmpty()?"":(facts.isEmpty()?"":" · ")+runtime);TextView f=null;if(!line.isEmpty()){f=text(line,13);f.setTextColor(muted());f.setPadding(0,0,0,dp(10));body.addView(f);}
  Button primary=button("",null);primary.setTextColor(accentInk());primary.setTextSize(16);primary.setTypeface(null,1);primary.setSingleLine(true);primary.setEllipsize(android.text.TextUtils.TruncateAt.END);primary.setBackground(rounded(accentFill(),24));primary.setBackgroundTintList(null);LinearLayout.LayoutParams pl=new LinearLayout.LayoutParams(-1,dp(48));pl.bottomMargin=dp(12);body.addView(primary,pl);
  String type=item.optString("Type");
  if("Movie".equals(type)||"Episode".equals(type)){primary.setText(meta.optLong("emby.resumeMs")>10000?"▶  继续播放":"▶  播放");primary.setOnClickListener(v->EmbyPlayback.playItem(this,server,item.optString("Id")));}
  else{primary.setText("正在读取剧集…");primary.setEnabled(false);}
  String overview=meta.optString("description");TextView ov=text(overview.isEmpty()?"暂无简介":overview,14);ov.setLineSpacing(dp(3),1f);ov.setMaxLines(4);ov.setEllipsize(android.text.TextUtils.TruncateAt.END);ov.setOnClickListener(v->{boolean open=ov.getMaxLines()!=Integer.MAX_VALUE;ov.setMaxLines(open?Integer.MAX_VALUE:4);});body.addView(ov);DetailLandscape.overlay(this,hero,heroH,surface(),name,f,primary,ov);
  if("Series".equals(type)){
   LinearLayout list=new LinearLayout(this);list.setOrientation(1);
   if(seasons!=null&&seasons.length()>1){HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);hs.addView(chips);LinearLayout.LayoutParams hsl=new LinearLayout.LayoutParams(-1,-2);hsl.topMargin=dp(14);body.addView(hs,hsl);
    for(int i=0;i<seasons.length();i++){JSONObject season=seasons.optJSONObject(i);if(season==null)continue;final int at=i;String label=season.optString("Name","第 "+season.optInt("IndexNumber",i+1)+" 季");TextView chip=text(label,14);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(16),0,dp(16),0);chip.setTag(season.optString("Id"));LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(-2,dp(36));cl.rightMargin=dp(8);chips.addView(chip,cl);chip.setOnClickListener(v->{paintChips(chips,at);seasonEpisodes(server,item.optString("Id"),season.optString("Id"),list,primary,false);});}
    paintChips(chips,0);}
   else if(seasons!=null&&seasons.length()==1){TextView h=text(seasons.optJSONObject(0)==null?"剧集":seasons.optJSONObject(0).optString("Name","剧集"),16);h.setTypeface(null,1);h.setPadding(0,dp(16),0,dp(4));body.addView(h);}
   LinearLayout.LayoutParams ll=new LinearLayout.LayoutParams(-1,-2);ll.topMargin=dp(8);body.addView(list,ll);
   String first=seasons!=null&&seasons.length()>0&&seasons.optJSONObject(0)!=null?seasons.optJSONObject(0).optString("Id"):"";
   seasonEpisodes(server,item.optString("Id"),first,list,primary,true);
  }
 }catch(Exception e){status.setText(EmbyApi.explain(e));}}
 /** 0.1.106：详情页右上角「收藏」（剧集收藏后追更新）；电影 / 单集多一个「下载」。 */
 void detailExtras(JSONObject server,JSONObject item,JSONObject meta){try{LinearLayout header=(LinearLayout)root.getChildAt(0);for(int i=header.getChildCount()-1;i>=0;i--){Object tag=header.getChildAt(i).getTag();if("mp-fav".equals(tag)||"mp-dl".equals(tag))header.removeViewAt(i);}
  String type=item.optString("Type");if("Movie".equals(type)||"Episode".equals(type)){TextView dl=text("⬇ 下载",15);dl.setTag("mp-dl");dl.setGravity(Gravity.CENTER);dl.setPadding(dp(12),0,dp(12),0);dl.setContentDescription("下载到本机，离线观看");String name=meta.optString("name")+("Episode".equals(type)?" · "+EmbyApi.line(item):"");dl.setOnClickListener(v->OfflineDownloads.emby(this,server,item.optString("Id"),name,meta));header.addView(dl,new LinearLayout.LayoutParams(-2,dp(44)));}
  header.addView(FollowUp.heart(this,meta,ink()),new LinearLayout.LayoutParams(-2,dp(44)));
  if("Series".equals(type))FollowUp.openedEmby(this,server,item.optString("Id"),meta.optString("id"));}catch(Exception ignored){}}
 void paintChips(LinearLayout chips,int on){for(int i=0;i<chips.getChildCount();i++){View c=chips.getChildAt(i);boolean sel=i==on;c.setBackground(rounded(sel?accentFill():(light?0x14000000:0x24ffffff),18));if(c instanceof TextView)((TextView)c).setTextColor(sel?accentInk():ink());}}
 /** 在详情页内加载一季的集；首次加载时顺便决定主按钮播哪一集（有进度的 → 第一个没看完的 → 第一集）。 */
 void seasonEpisodes(JSONObject server,String seriesId,String seasonId,LinearLayout list,Button primary,boolean decidePrimary){
  list.removeAllViews();TextView wait=text("正在读取剧集…",13);wait.setTextColor(muted());list.addView(wait);final int token=epoch;
  io.submit(()->{try{JSONArray items=EmbyClient.episodesAll(this,server,seriesId,seasonId);runOnUiThread(()->{if(dead||token!=epoch)return;list.removeAllViews();
    if(items==null||items.length()==0){TextView none=text("这一季暂时没有剧集",14);none.setTextColor(muted());list.addView(none);if(decidePrimary){primary.setText("暂无可播放的剧集");}return;}
    JSONObject resume=null,unplayed=null;
    for(int i=0;i<items.length();i++){JSONObject ep=items.optJSONObject(i);if(ep==null)continue;JSONObject ud=ep.optJSONObject("UserData");boolean played=ud!=null&&ud.optBoolean("Played");long pos=ud==null?0:ud.optLong("PlaybackPositionTicks");if(resume==null&&pos>0&&!played)resume=ep;if(unplayed==null&&!played)unplayed=ep;
     String label=EmbyApi.line(ep);if(label.isEmpty()||label.equals("续播"))label=ep.optString("Name","剧集");String mark=played?"  ✓":pos>0?"  · 看到一半":"";String id=ep.optString("Id");
     Button b=button(label+mark,()->EmbyPlayback.playItem(this,server,id));final String dlName=ep.optString("SeriesName",title.getText().toString())+" · "+label;b.setOnLongClickListener(v->{OfflineDownloads.emby(this,server,id,dlName,null);return true;});b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);if(played)b.setTextColor(muted());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(6);list.addView(b,p);}
    if(decidePrimary){JSONObject pick=resume!=null?resume:unplayed!=null?unplayed:items.optJSONObject(0);if(pick!=null){String l=EmbyApi.line(pick);if(l.isEmpty()||l.equals("续播"))l=pick.optString("Name");primary.setText((resume!=null?"▶  继续 ":"▶  播放 ")+l);primary.setEnabled(true);String id=pick.optString("Id");primary.setOnClickListener(v->EmbyPlayback.playItem(this,server,id));}}
   });}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;list.removeAllViews();TextView err=text(EmbyApi.explain(e),13);err.setTextColor(muted());list.addView(err);});}});
 }
